style.css:
@-moz-document domain("roblox.com") {
html, body {
    background: url("https://i.imgur.com/TeowIQH.jpeg") no-repeat center center fixed !important;
    background-size: cover !important;
    background-attachment: fixed !important;
    background-color: transparent !important;
  }

  /* Roblox main layout sections */
  .theme-base,
  .container-main,
  .page-content,
  .rbx-body,
  .content,
  .home-container,
  .profile-container,
  #app,
  #container-main {
    background: transparent !important;
    background-color: transparent !important;
  }

  /* RoPro injected panels */
  div[id*="ropro"],
  [class*="ropro"] {
    background: transparent !important;
    background-color: transparent !important;
  }

  /* Optional - fix white cards or UI blocks */
  .game-card,
  .card-item,
  .section-content,
  .rbx-carousel,
  .game-details-container {
    background: rgba(255, 255, 255, 0.05) !important; /* semi-transparent */
    backdrop-filter: blur(4px);
  }
}
